import{z as i,x as o,o as B,c as d,q as r,j as n,D as a,d as e,s as l,S as s,b as A}from"./chunks/framework.C8m1ZpeB.js";const S=JSON.parse('{"title":"互换在组合里","description":"","frontmatter":{"title":"互换在组合里","date":"2026-09-18T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/bm2-swaps-in-portfolio.md","filePath":"quant/bm2-swaps-in-portfolio.md","lastUpdated":1791413859000}'),D={name:"quant/bm2-swaps-in-portfolio.md"};function p(F,E,u,C,m,f){const t=o("Mermaid");return B(),d("div",null,[E[2]||(E[2]=r('<h1 id="互换在组合里" tabindex="-1">互换在组合里 <a class="header-anchor" href="#互换在组合里" aria-label="Permalink to &quot;互换在组合里&quot;">​</a></h1><div class="epigraph"><p>互换不挪动本金，只换现金流的利率形态；于是久期管理多了一种不必卖券、不必备货的工具——代价是签下一个对手方与一纸抵押条款。</p><footer>—— 据 Fabozzi, Bond Markets, Analysis and Strategies 互换章节整理</footer></div><p><a href="/quant/bm2-treasury-futures">上一课</a>把久期交给交易所合约，刻度受交割篮与离散到期档位的限制。互换补上另外半张地图：期限任选、条款可定制、长端照样有深度。本课写互换进入组合的两种基本动作——加久期与换现金流——以及随之而来的利差敞口、抵押与对手方问题。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>期货够不着的部分有两种。其一是期限：30 年档的负债久期，期货只有临近档位，插档误差大；互换的 20 年、30 年报价连续且有真实流量。其二是现金流形态：一只固定票息信用债在组合里的问题是「利率久期占预算、利差才是想要的东西」；一个浮动利率负债方的问题是「怕利率上行」——两者都需要在不卖出资产的前提下改写现金流的固定/浮动属性。互换正是干这个的：名义本金不动，只交换固定与浮动腿。多曲线时代它的折现与投影分属两条曲线（见 <a href="/quant/multi-curve-ois">OIS 与多曲线</a>），估值先从这条口径开始。</p><p><span class="marginnote">术语翻译：利率互换就是「只换利息、不换本金」的协议。比如名义本金 1 亿元，A 答应每年按固定 3.5% 付息，B 答应按浮动基准付息，每期只结清两边利息的差额——本金从头到尾只在纸面上用来算利息，谁也不用真拿出来。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>两个基本动作。加久期：收入固定、支付浮动的互换，DV01 集中在固定腿，等效于借入一笔不占本金的固息头寸；长端负债匹配用它补期货够不到的桶，暴露按互换 DV01 与利差 DV01 两个口径分别记账（后者即 <a href="/quant/swap-spread">互换利差</a> 的敞口）。换现金流：资产互换是买债加支付固定的一揽子交易，把固定票息债变成合成浮动，投资者保留信用风险、收到的利差是相对浮动基准的资产互换利差——「利率归互换、信用归自己」的分工由此完成；反向的动作则是负债方把浮动支付换进固定，锁定融资成本。两种动作都 unfunded，但 CSA 让抵押日结：账户里要为利差反向与利率反向各留一条现金通道。</p>',8)),(B(),n(s,null,{default:a(()=>[l(t,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20N%5B%22%E9%9C%80%E6%B1%82%EF%BC%9A%E9%95%BF%E7%AB%AF%E4%B9%85%E6%9C%9F%E6%88%96%E7%8E%B0%E9%87%91%E6%B5%81%E6%8D%A2%E5%9E%8B%22%5D%20--%3E%20A%5B%22%E6%94%B6%E5%9B%BA%E4%BA%92%E6%8D%A2%EF%BC%9A%E5%8A%A0%E4%B9%85%E6%9C%9F%EF%BC%8C%E6%9C%AC%E9%87%91%E4%B8%8D%E5%8A%A8%22%5D%0A%20%20N%20--%3E%20B%5B%22%E8%B5%84%E4%BA%A7%E4%BA%92%E6%8D%A2%EF%BC%9A%E5%9B%BA%E5%AE%9A%E7%A5%A8%E6%81%AF%E6%8D%A2%E6%B5%AE%E5%8A%A8%EF%BC%8C%E4%BF%A1%E7%94%A8%E5%88%A9%E5%B7%AE%E4%BF%9D%E7%95%99%22%5D%0A%20%20A%20--%3E%20M%5B%22%E6%9A%B4%E9%9C%B2%E8%AE%B0%E8%B4%A6%EF%BC%9A%E4%BA%92%E6%8D%A2%20DV01%20%E4%B8%8E%E5%88%A9%E5%B7%AE%20DV01%20%E5%88%86%E5%88%97%22%5D%0A%20%20B%20--%3E%20M%0A%20%20M%20--%3E%20CSA%5B%22%E6%8A%B5%E6%8A%BC%E6%9D%A1%E6%AC%BE%E5%86%B3%E5%AE%9A%E7%8E%B0%E9%87%91%E8%B7%AF%E5%BE%84%22%5D%0A%20%20CSA%20--%3E%20ST%5B%22%E5%8E%8B%E5%8A%9B%EF%BC%9A%E5%88%A9%E5%B7%AE%E8%B5%B0%E9%98%94%E4%B8%8E%E8%BF%BD%E4%BF%9D%E5%90%8C%E6%97%B6%E5%8F%91%E7%94%9F%22%5D%0A%20%20ST%20--%3E%20GV%7B%22%E6%9D%A1%E6%AC%BE%E8%83%BD%E5%90%A6%E6%89%BF%E5%8F%97%22%7D%0A%20%20GV%20--%3E%20Y%5B%22%E4%BF%9D%E7%95%99%E5%A4%B4%E5%AF%B8%E5%B9%B6%E7%9B%91%E6%8E%A7%22%5D%0A%20%20GV%20--%3E%20X%5B%22%E9%99%8D%E5%90%8D%E4%B9%89%E6%88%96%E8%B0%83%E6%95%B4%E6%8A%B5%E6%8A%BC%22%5D%0A"})]),fallback:a(()=>[...E[0]||(E[0]=[e(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=A("h2",{id:"机制",tabindex:"-1"},[e("机制 "),A("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=A("p",null,"互换 DV01 为什么集中在固定腿：浮动腿在每个重置日回到基准，利率变动只影响下一期；固定腿的现值则按整条折现曲线重估。所以收固互换在机制上是一串远期的组合，久期随期限近乎线性增长——这正是它补长端的资格。资产互换的机制则是一次分解：债券价格被拆成利率部分与信用部分，利率部分被互换对掉，剩下的合成浮动利差是市场对信用的报价。这条分解让组合第一次能把「我要信用」与「我不要利率」写成两个独立的头寸。机制的反面是基差：互换曲线与国债曲线是两个市场，2020 年 3 月融资挤压与避险买入同向发生，互换利差数日内大幅走阔——同时持有国债与互换的组合在那一刻才看清这是两个市场的价格。",-1)),E[5]||(E[5]=A("p",null,[A("span",{class:"marginnote"},"资产互换不消灭信用风险，只是打包：投资者仍承担债券违约损失，另加互换对手风险。资产互换利差与国债利差（G-spread）分属不同折现曲线，直接比较会错位——先统一口径再谈哪只券「便宜」。")],-1)),E[6]||(E[6]=A("p",null,[A("span",{class:"marginnote"},"直觉类比：浮动腿像游标卡尺——每次重置都滑回基准，利率变动只影响下一期利息；固定腿像一根整长的定长刻度——整条折现曲线动，它都跟着重估。所以收固互换的 DV01 几乎全在固定腿，近似于一张同期限固息债的敏感度，久期随期限近乎线性增长。")],-1)),(B(),n(s,null,{default:a(()=>[l(t,{id:"mermaid-35",class:"mermaid",graph:"flowchart%20TD%0A%20%20B%5B%22%E5%9B%BA%E5%AE%9A%E7%A5%A8%E6%81%AF%E4%BF%A1%E7%94%A8%E5%80%BA%22%5D%20--%3E%20D%5B%22%E8%B5%84%E4%BA%A7%E4%BA%92%E6%8D%A2%E5%88%86%E8%A7%A3%EF%BC%9A%E5%88%A9%E7%8E%87%E8%85%BF%E4%B8%8E%E4%BF%A1%E7%94%A8%E8%85%BF%22%5D%0A%20%20D%20--%3E%20I%5B%22%E5%88%A9%E7%8E%87%E8%85%BF%EF%BC%9A%E7%AD%BE%E6%94%B6%E5%9B%BA%E5%AE%9A%E3%80%81%E4%BB%98%E6%B5%AE%E5%8A%A8%E7%9A%84%E4%BA%92%E6%8D%A2%E5%AF%B9%E6%8E%89%22%5D%0A%20%20D%20--%3E%20C%5B%22%E4%BF%A1%E7%94%A8%E8%85%BF%EF%BC%9A%E8%BF%9D%E7%BA%A6%E9%A3%8E%E9%99%A9%E7%95%99%E5%9C%A8%E8%87%AA%E5%B7%B1%E8%B4%A6%E4%B8%8A%22%5D%0A%20%20I%20--%3E%20R%5B%22%E6%94%B6%E5%88%B0%E6%B5%AE%E5%8A%A8%E5%9F%BA%E5%87%86%E5%8A%A0%E5%87%8F%E4%BB%B7%E5%B7%AE%22%5D%0A%20%20C%20--%3E%20S%5B%22%E5%90%88%E6%88%90%E8%B5%84%E4%BA%A7%E4%BA%92%E6%8D%A2%E5%88%A9%E5%B7%AE%22%5D%0A%20%20R%20--%3E%20S%0A%20%20S%20--%3E%20P%5B%22%E4%B8%A4%E4%B8%AA%E5%A4%B4%E5%AF%B8%E6%AD%A4%E5%90%8E%E5%8F%AF%E7%8B%AC%E7%AB%8B%E8%B0%83%E4%BB%93%22%5D%0A"})]),fallback:a(()=>[...E[1]||(E[1]=[e(" Loading... ",-1)])]),_:1})),E[7]||(E[7]=r('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>无抵押或有抵押不足的互换带对手方风险，估值要计 CVA——这是 <a href="/quant/rc-xva-linkage">XVA 联动</a> 一课的领地；有抵押的互换则把风险移到条款执行上，2020 与 2022 都验证过抵押渠道优先于价格渠道。期货与互换的分工是成本函数：液体档位期货更便宜，长端与定制条款互换占优，两者并用时还有期货—互换基差要对账。资产互换的退出依赖两个市场的流动性同时在线，压券时往往只剩一个。最后，会计与税务对「合成头寸」的处理可能与经济对冲不一致，方案落地前先过合规口径。</p><p><span class="marginnote">常见误区：初学者以为签完互换对冲就「完工」了，忘了对手方本身可能违约——对手倒下时，你手里那张对冲凭证跟着贬值，估值里为此扣掉的价钱就是 CVA。有抵押（CSA）的互换把这一风险换成条款执行风险：押品给不给、给得快不快，成了新的生死线。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>互换的两个动作：收固加久期（DV01 在固定腿）、资产互换换现金流（信用归自己、利率归对手）。</li><li>暴露分两本账：互换 DV01 与利差 DV01，混记会把利差观点误当利率对冲。</li><li>unfunded 是记账口径，CSA 抵押让风险落在现金通道与条款执行上。</li><li>期货管液体档位、互换管长端与定制，并用时须对基差记账。</li><li>出处：据 Fabozzi 互换章节整理；多曲线与利差口径见本站 OIS 多曲线与互换利差相关课。</li></ul>',5))])}const V=i(D,[["render",p]]);export{S as __pageData,V as default};
